def exp_for_level(level: int) -> int:
    return int(100 * (level ** 1.5))

# ============================================================
# БАЗА ДАННЫХ
# ============================================================

async def init_db():
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("""
            CREATE TABLE IF NOT EXISTS characters (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                telegram_id INTEGER UNIQUE,
                username TEXT,
                name TEXT,
                class TEXT,
                level INTEGER DEFAULT 1,
                exp INTEGER DEFAULT 0,
                hp INTEGER DEFAULT 100,
                max_hp INTEGER DEFAULT 100,
                mana INTEGER DEFAULT 50,
                max_mana INTEGER DEFAULT 50,
                attack INTEGER DEFAULT 10,
                defense INTEGER DEFAULT 5,
                cash INTEGER DEFAULT 0,
                diamonds INTEGER DEFAULT 0,
                kills INTEGER DEFAULT 0,
                weapon TEXT DEFAULT NULL,
                armor TEXT DEFAULT NULL,
                job TEXT DEFAULT NULL,
                job_started INTEGER DEFAULT NULL,
                job_last_paid INTEGER DEFAULT NULL,
                bottles_last INTEGER DEFAULT 0,
                last_regen INTEGER DEFAULT 0,
                gang_last_encounter INTEGER DEFAULT 0,
                gang_last_collect INTEGER DEFAULT 0,
                gang_discount_until INTEGER DEFAULT 0,
                gang_weapon_discount_until INTEGER DEFAULT 0,
                referred_by INTEGER DEFAULT NULL,
                last_hunt INTEGER DEFAULT 0,
                channel_verified INTEGER DEFAULT 0,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        """)
        # Миграция для существующих баз
        for col, definition in [
            ("job", "TEXT DEFAULT NULL"),
            ("job_started", "INTEGER DEFAULT NULL"),
            ("job_last_paid", "INTEGER DEFAULT NULL"),
            ("bottles_last", "INTEGER DEFAULT 0"),
            ("last_regen", "INTEGER DEFAULT 0"),
            ("gang_last_encounter", "INTEGER DEFAULT 0"),
            ("hospital_until",      "INTEGER DEFAULT 0"),
            ("gang_last_collect", "INTEGER DEFAULT 0"),
            ("gang_discount_until", "INTEGER DEFAULT 0"),
            ("gang_weapon_discount_until", "INTEGER DEFAULT 0"),
            ("street_find_money_at",  "INTEGER DEFAULT 0"),
            ("street_girl_at",        "INTEGER DEFAULT 0"),
            ("street_dog_at",         "INTEGER DEFAULT 0"),
            ("street_cop_at",         "INTEGER DEFAULT 0"),
            ("street_witness_at",     "INTEGER DEFAULT 0"),
            ("street_event_at",       "INTEGER DEFAULT 0"),
        ("street_last_event_at",  "INTEGER DEFAULT 0"),
            ("referred_by", "INTEGER DEFAULT NULL"),
            ("ref_bonus_given", "INTEGER DEFAULT 0"),
            ("last_hunt", "INTEGER DEFAULT 0"),
            ("channel_verified", "INTEGER DEFAULT 0"),
            ("wanted_stars", "INTEGER DEFAULT 0"),
            ("jail_until", "INTEGER DEFAULT 0"),
            ("jail_count", "INTEGER DEFAULT 0"),
            ("wanted_last_fine", "INTEGER DEFAULT 0"),
            # === Звёзды банд + плен (jobs v2) ===
            ("wanted_gangs",     "INTEGER DEFAULT 0"),
            ("captivity_until",  "INTEGER DEFAULT 0"),
            ("captivity_count",  "INTEGER DEFAULT 0"),
            ("gather_port",    "INTEGER DEFAULT 0"),
            ("gather_casino",  "INTEGER DEFAULT 0"),
            ("gather_factory", "INTEGER DEFAULT 0"),
            ("gather_mansion", "INTEGER DEFAULT 0"),
            # Критические колонки — без них падают shop и character_info
            ("diamonds", "INTEGER DEFAULT 0"),
            ("kills",    "INTEGER DEFAULT 0"),
            ("weapon",   "TEXT DEFAULT NULL"),
            ("armor",    "TEXT DEFAULT NULL"),
            ("max_hp",   "INTEGER DEFAULT 100"),
            ("max_mana", "INTEGER DEFAULT 50"),
            # Внешность персонажа (JSON: skin,body,face,hair,hat)
            ("look_json", "TEXT DEFAULT NULL"),
            # Кулдауны работ: JSON {job_id: until_ts}
            ("job_cooldowns_json", "TEXT DEFAULT NULL"),
            # Кулдаун событий мини-аппа (события по игровому времени)
            ("last_hub_event_at", "INTEGER DEFAULT 0"),
            # Phase 9: 5 прокачиваемых навыков (0..5).
            #  safecracker — вскрывает сейфы на боях (уровень ≤ skill_lvl)
            #  marksman    — +урон из любого оружия
            #  stealth     — уменьшает радиус обзора врагов в бою
            #  toughness   — +max HP в бою
            #  hustler     — +% к деньгам с боёв и работ
            ("safecracker_level", "INTEGER DEFAULT 0"),
            ("marksman_level",    "INTEGER DEFAULT 0"),
            ("stealth_level",     "INTEGER DEFAULT 0"),
            ("toughness_level",   "INTEGER DEFAULT 0"),
            ("hustler_level",     "INTEGER DEFAULT 0"),
            # Кулдауны сейфов per (uid, boss_id). JSON {"kosoy": 1715000000, ...}
            # Сейф появляется на карте каждого босса раз в час (SAFE_RESPAWN_S).
            ("safe_cooldowns_json", "TEXT DEFAULT NULL"),
            # Отложенный coop_sid: если друг перешёл по инвайт-ссылке, но у него
            # ещё не создан персонаж — сохраняем sid сюда. После завершения
            # creator-flow build_hub_url прокинет coop_sid в URL и хаб сразу
            # сделает /coop/<sid>/join. Колонка очищается после первого
            # успешного построения URL с coop_sid.
            ("pending_coop_sid",   "TEXT DEFAULT NULL"),
            # Название банды лидера. Рендерится над захваченными в открытом
            # мире районами рядом с флагом. Имеет смысл только у лидера —
            # обычные члены банды берут имя у своего leader_id.
            ("gang_name",          "TEXT DEFAULT NULL"),
            # JSON-список boss_id'ов которых игрок хоть раз победил. Для
            # галочки «✓ побеждал» в списке боссов района (визуальный маркер).
            ("bosses_defeated_json", "TEXT DEFAULT NULL"),
            # Выбранная точка респавна в открытом мире. NULL/«hospital» =
            # дефолтный спавн у госпиталя. Иначе biz_id из BUSINESSES
            # (coffee/carwash/...) — респ рядом с купленным бизнесом.
            ("respawn_point",      "TEXT DEFAULT NULL"),
            ("building_loot_at",   "INTEGER DEFAULT 0"),
            # Пляжные находки: постоянная репутация и серия честных возвратов.
            ("good_name",          "INTEGER DEFAULT 0"),
            ("lost_returns",       "INTEGER DEFAULT 0"),
            ("lost_return_streak", "INTEGER DEFAULT 0"),
            # Отдельная постоянная карьера полиции. Не сбрасывается при увольнении.
            ("police_xp",          "INTEGER DEFAULT 0"),
            # Постоянная карьера мафиози. Не сбрасывается при службе в полиции.
            ("mafia_xp",           "INTEGER DEFAULT 0"),
        ]:
            try:
                await db.execute(f"ALTER TABLE characters ADD COLUMN {col} {definition}")
            except Exception:
                pass
        await db.execute("""
            CREATE TABLE IF NOT EXISTS inventory (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                telegram_id INTEGER,
                item_id TEXT,
                quantity INTEGER DEFAULT 1
            )
        """)
        # Старые версии могли создать несколько строк одного предмета. Сначала
        # объединяем их, затем запрещаем дубли на уровне SQLite.
        async with db.execute("SELECT 1 FROM sqlite_master WHERE type='index' AND name='ux_inventory_owner_item'") as cur:
            inventory_index_ready = await cur.fetchone()
        if not inventory_index_ready:
            await db.execute("""
                UPDATE inventory
                   SET quantity = (SELECT SUM(i2.quantity) FROM inventory i2
                                    WHERE i2.telegram_id=inventory.telegram_id
                                      AND i2.item_id=inventory.item_id)
                 WHERE id IN (SELECT MIN(id) FROM inventory GROUP BY telegram_id,item_id)
            """)
            await db.execute("""
                DELETE FROM inventory
                 WHERE id NOT IN (SELECT MIN(id) FROM inventory GROUP BY telegram_id,item_id)
            """)
            await db.execute("CREATE UNIQUE INDEX ux_inventory_owner_item ON inventory(telegram_id,item_id)")
        await db.execute("""
            CREATE TABLE IF NOT EXISTS active_battles (
                telegram_id INTEGER PRIMARY KEY,
                location TEXT,
                boss_id TEXT,
                boss_hp INTEGER,
                boss_max_hp INTEGER,
                party_json TEXT DEFAULT NULL
            )
        """)
        # Миграция: добавить party_json если отсутствует
        try:
            await db.execute("ALTER TABLE active_battles ADD COLUMN party_json TEXT DEFAULT NULL")
        except Exception:
            pass
        # Миграция: props_used_json для учёта использованного имущества в бою
        try:
            await db.execute("ALTER TABLE active_battles ADD COLUMN props_used_json TEXT DEFAULT NULL")
        except Exception:
            pass
        # Миграция: добавить current_hp в gang_members если отсутствует
        try:
            await db.execute("ALTER TABLE gang_members ADD COLUMN current_hp INTEGER DEFAULT NULL")
        except Exception:
            pass
        # Миграция: host_alive / partner_alive для coop_sessions
        for _col in ("host_alive INTEGER DEFAULT 1", "partner_alive INTEGER DEFAULT 1"):
            try:
                await db.execute(f"ALTER TABLE coop_sessions ADD COLUMN {_col}")
            except Exception:
                pass
        # Миграция: players_json для поддержки до 4 игроков
        try:
            await db.execute("ALTER TABLE coop_sessions ADD COLUMN players_json TEXT DEFAULT NULL")
        except Exception:
            pass
        await db.execute("""
            CREATE TABLE IF NOT EXISTS district_control (
                location_id TEXT PRIMARY KEY,
                telegram_id INTEGER,
                telegram_name TEXT,
                captured_at REAL,
                last_collected REAL DEFAULT 0
            )
        """)
        # Автоматическая городская газета. Сюда попадают только крупные
        # серверные события; выпуск за 24 часа одинаков для всех игроков и
        # переживает перезапуск процесса.
        await db.execute("""
            CREATE TABLE IF NOT EXISTS city_news (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                kind        TEXT NOT NULL,
                icon        TEXT NOT NULL DEFAULT '🗞',
                headline    TEXT NOT NULL,
                summary     TEXT NOT NULL DEFAULT '',
                actor_uid   TEXT DEFAULT NULL,
                dedupe_key  TEXT UNIQUE,
                created_at  INTEGER NOT NULL
            )
        """)
        await db.execute(
            "CREATE INDEX IF NOT EXISTS ix_city_news_created_at "
            "ON city_news(created_at DESC)"
        )
        # Бизнесы игроков (пассивный доход)
        # status: 'ok' | 'blocked' | 'burned'
        await db.execute("""
            CREATE TABLE IF NOT EXISTS player_businesses (
                telegram_id  INTEGER NOT NULL,
                biz_id       TEXT    NOT NULL,
                bought_at    INTEGER NOT NULL,
                last_collect INTEGER NOT NULL,
                status       TEXT    DEFAULT 'ok',
                blocked_until INTEGER DEFAULT 0,
                last_event_at INTEGER DEFAULT 0,
                pending_notice TEXT DEFAULT NULL,
                level         INTEGER DEFAULT 1,
                PRIMARY KEY (telegram_id, biz_id)
            )
        """)
        try:
            await db.execute("ALTER TABLE player_businesses ADD COLUMN level INTEGER DEFAULT 1")
        except Exception:
            pass
        await db.execute("""
            CREATE TABLE IF NOT EXISTS business_assistants (
                telegram_id      INTEGER PRIMARY KEY,
                hired_at         INTEGER NOT NULL,
                salary_paid_until INTEGER NOT NULL
            )
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS gang_members (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                telegram_id INTEGER,
                member_name TEXT,
                role TEXT,
                role_display TEXT,
                last_collected INTEGER DEFAULT 0,
                current_hp INTEGER DEFAULT NULL
            )
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS friend_collects (
                inviter_id INTEGER,
                friend_id  INTEGER,
                last_collect INTEGER DEFAULT 0,
                PRIMARY KEY (inviter_id, friend_id)
            )
        """)
        # Общий «банк банды»: пирамида referred_by → лидер. Каждое
        # эмерджентное событие (инкассатор и т.п.) откладывает 20%
        # от награды в пул лидера. Раз в 3 дня СЕРВЕР сам делит пул
        # поровну между всеми членами банды (включая лидера) — без
        # ручного клика. Кладём расписание в next_payout.
        await db.execute("""
            CREATE TABLE IF NOT EXISTS gang_pools (
                leader_id    INTEGER PRIMARY KEY,
                pool         INTEGER DEFAULT 0,
                last_payout  INTEGER DEFAULT 0,
                total_earned INTEGER DEFAULT 0,
                last_event_t INTEGER DEFAULT 0,
                next_payout  INTEGER DEFAULT 0
            )
        """)
        # Миграция: добавить next_payout если БД старая
        try:
            await db.execute("ALTER TABLE gang_pools ADD COLUMN next_payout INTEGER DEFAULT 0")
        except Exception:
            pass
        # Очередь уведомлений для показа баннером при следующем заходе
        # игрока в мир (доход от банды / бизнес / работа / событие и т.п.)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS pending_notifications (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                telegram_id INTEGER,
                kind        TEXT,
                title       TEXT,
                msg         TEXT,
                amount      INTEGER DEFAULT 0,
                ts          INTEGER DEFAULT 0,
                seen        INTEGER DEFAULT 0
            )
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS contacts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                telegram_id INTEGER,
                contact_type TEXT,
                contact_name TEXT,
                received_at INTEGER DEFAULT 0,
                used INTEGER DEFAULT 0
            )
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS property_owned (
                telegram_id INTEGER,
                item_id TEXT,
                bought_at INTEGER DEFAULT 0,
                PRIMARY KEY (telegram_id, item_id)
            )
        """)
        # Миграция: добавить поле district guard / sabotage
        for col, definition in [
            ("guard_json",      "TEXT DEFAULT NULL"),
            ("sabotaged_until", "INTEGER DEFAULT 0"),
        ]:
            try:
                await db.execute(f"ALTER TABLE district_control ADD COLUMN {col} {definition}")
            except Exception:
                pass
        # Таблица рейдов
        await db.execute("""
            CREATE TABLE IF NOT EXISTS raid_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                location_id TEXT,
                owner_id INTEGER,
                gang_name TEXT,
                gang_emoji TEXT,
                boss_hp_max INTEGER,
                boss_hp INTEGER,
                boss_atk INTEGER,
                boss_def INTEGER,
                reward_cash INTEGER,
                reward_exp INTEGER,
                started_at INTEGER,
                expires_at INTEGER,
                status TEXT DEFAULT 'active'
            )
        """)
        await db.execute("""
            CREATE TABLE IF NOT EXISTS coop_sessions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                host_id INTEGER NOT NULL,
                partner_id INTEGER NOT NULL,
                boss_id TEXT NOT NULL,
                boss_hp INTEGER NOT NULL,
                boss_max_hp INTEGER NOT NULL,
                location TEXT NOT NULL,
                party_json TEXT,
                current_turn INTEGER DEFAULT 0,
                status TEXT DEFAULT 'pending',
                created_at INTEGER NOT NULL
            )
        """)
        # При старте — очищаем все зависшие active/pending co-op сессии
        await db.execute(
            "UPDATE coop_sessions SET status='cancelled' WHERE status IN ('active','pending')"
        )
        # Кулдаун ограблений: одна точка раз в 24ч на игрока.
        # Запись с (uid, biz_id) активна 24ч после t — потом игнорится
        # (запросы сами фильтруют по t > now-86400).
        await db.execute("""
            CREATE TABLE IF NOT EXISTS shop_robs (
                uid     INTEGER NOT NULL,
                biz_id  TEXT NOT NULL,
                t       INTEGER NOT NULL,
                PRIMARY KEY (uid, biz_id)
            )
        """)
        # Бригадир — хит-контракты. Лимит BRIGADIR_DAILY_LIMIT за сутки на игрока.
        # Каждый append — отдельная запись (kill_t = когда сдан, или 0 если выдан).
        await db.execute("""
            CREATE TABLE IF NOT EXISTS brigadir_kills (
                id      INTEGER PRIMARY KEY AUTOINCREMENT,
                uid     INTEGER NOT NULL,
                t       INTEGER NOT NULL,
                stealth INTEGER NOT NULL DEFAULT 0,
                reward  INTEGER NOT NULL DEFAULT 0
            )
        """)
        # Налёты на банк — лимит 1/24ч на игрока.
        await db.execute("""
            CREATE TABLE IF NOT EXISTS bank_heists (
                id      INTEGER PRIMARY KEY AUTOINCREMENT,
                uid     INTEGER NOT NULL,
                t       INTEGER NOT NULL,
                reward  INTEGER NOT NULL DEFAULT 0
            )
        """)
        # Первый денежный бонус за арест конкретного онлайн-игрока во всём
        # мире. UNIQUE по target_uid не позволяет друзьям менять копа и снова
        # получать деньги: повторные доставки остаются действием, но без $.
        await db.execute("""
            CREATE TABLE IF NOT EXISTS police_online_rewards (
                target_uid  INTEGER PRIMARY KEY,
                cop_uid     INTEGER NOT NULL,
                arrested_at INTEGER NOT NULL,
                UNIQUE (target_uid)
            )
        """)
        await db.execute("CREATE UNIQUE INDEX IF NOT EXISTS ux_police_online_reward_target ON police_online_rewards(target_uid)")
        # Общий суточный лимит успешных задержаний: онлайн-игроки и NPC
        # используют один атомарный счётчик, поэтому сменой типа цели лимит
        # обойти нельзя. День считается по локальному времени сервера.
        await db.execute("""
            CREATE TABLE IF NOT EXISTS police_daily_arrests (
                cop_uid INTEGER NOT NULL,
                day     TEXT NOT NULL,
                count   INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (cop_uid, day)
            )
        """)
        # При старте — очищаем все зависшие active_battles (на случай краша)
        await db.execute("DELETE FROM active_battles")
        # Jobs v2 — снимаем старые job-id (janitor/shawarma/etc), их в новом JOBS нет.
        # Если игрок был на старой работе — просто слетит (без выплаты, поскольку
        # автоматический pay был ранее уже начислен).
        await db.execute(
            "UPDATE characters SET job=NULL, job_started=NULL, job_last_paid=NULL "
            "WHERE job IS NOT NULL AND job NOT IN ('newspapers','bikes','shawarma_runner','lookout','stall_tax','thimblerig','moonshine','car_jacker','blackmail','arson','smuggling','forger','boss_car','bank_heist','prosecutor_car')"
        )
        await db.commit()


POLICE_LEVEL_XP = (0, 300, 800, 1600, 2800)
POLICE_DAILY_LIMITS = (3, 6, 9, 12, None)


def police_level_from_xp(xp: int) -> int:
    xp = max(0, int(xp or 0))
    level = 1
    for idx, threshold in enumerate(POLICE_LEVEL_XP, 1):
        if xp >= threshold:
            level = idx
    return level


def police_daily_limit_from_xp(xp: int) -> int | None:
    return POLICE_DAILY_LIMITS[police_level_from_xp(xp) - 1]


def police_day_key(now: float | None = None) -> str:
    return time.strftime('%Y-%m-%d', time.localtime(now or time.time()))


async def police_daily_state(cop_uid: int, police_xp: int) -> dict:
    day = police_day_key()
    async with aiosqlite.connect(DB_PATH) as db:
        async with db.execute(
                "SELECT count FROM police_daily_arrests WHERE cop_uid=? AND day=?",
                (int(cop_uid), day)) as cur:
            row = await cur.fetchone()
    count = int(row[0]) if row else 0
    return {'day': day, 'count': count,
            'limit': police_daily_limit_from_xp(police_xp)}


async def police_claim_daily_arrest(cop_uid: int, police_xp: int) -> dict:
    """Атомарно занимает одно место в суточном лимите копа."""
    day = police_day_key()
    limit = police_daily_limit_from_xp(police_xp)
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute('BEGIN IMMEDIATE')
        async with db.execute(
                "SELECT count FROM police_daily_arrests WHERE cop_uid=? AND day=?",
                (int(cop_uid), day)) as cur:
            row = await cur.fetchone()
        count = int(row[0]) if row else 0
        if limit is not None and count >= limit:
            await db.rollback()
            return {'ok': False, 'error': 'daily_limit', 'day': day,
                    'count': count, 'limit': limit}
        count += 1
        await db.execute(
            "INSERT INTO police_daily_arrests(cop_uid,day,count) VALUES(?,?,?) "
            "ON CONFLICT(cop_uid,day) DO UPDATE SET count=excluded.count",
            (int(cop_uid), day, count))
        await db.commit()
    return {'ok': True, 'day': day, 'count': count, 'limit': limit}


MAFIA_LEVEL_XP = (0, 400, 1100, 2300, 4000)
MAFIA_XP_MAX = MAFIA_LEVEL_XP[-1]
MAFIA_LEVEL_RANKS = ("Шестёрка", "Боец", "Капо", "Консильери", "Дон")
MAFIA_LEVEL_PERKS = (
    "Своя бригада до 5 бойцов",
    "Скидка 15% на найм и 90 HP у новых бойцов",
    "Можно нанимать боссов, сильное оружие и 115 HP",
    "Бригада до 6 бойцов и урон отряда +20%",
    "Бригада до 7 бойцов и урон отряда +35%",
)


def mafia_level_from_xp(xp: int) -> int:
    xp = max(0, int(xp or 0))
    level = 1
    for idx, threshold in enumerate(MAFIA_LEVEL_XP, 1):
        if xp >= threshold:
            level = idx
    return level


def career_progress_text(xp: int, thresholds: tuple[int, ...]) -> str:
    xp = max(0, int(xp or 0))
    level = 1
    for idx, threshold in enumerate(thresholds, 1):
        if xp >= threshold:
            level = idx
    if level >= len(thresholds):
        return f"{xp} XP · максимальный уровень"
    floor, target = thresholds[level - 1], thresholds[level]
    return f"{xp} XP · {xp - floor}/{target - floor} XP до {level + 1} уровня"


async def grant_mafia_xp(uid: int, amount: int, reason: str,
                         world_player: dict | None = None) -> dict:
    """Начисляет серверный опыт мафии только игроку вне полицейской службы."""
    if not world_player or not world_player.get('_mafia') or world_player.get('_police'):
        return {}
    amount = max(0, int(amount or 0))
    if not amount:
        return {}
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute(
            "UPDATE characters SET mafia_xp=MIN(?,COALESCE(mafia_xp,0)+?) "
            "WHERE telegram_id=?", (MAFIA_XP_MAX, amount, int(uid)))
        async with db.execute(
                "SELECT mafia_xp FROM characters WHERE telegram_id=?", (int(uid),)) as cur:
            row = await cur.fetchone()
        await db.commit()
    new_xp = int((row or [0])[0] or 0)
    old_xp = int((world_player or {}).get('_mafia_xp') or 0)
    gain = max(0, new_xp - old_xp)
    if world_player is not None:
        world_player['_mafia_xp'] = new_xp
    return {'mafia_xp': new_xp, 'mafia_xp_gain': gain,
            'mafia_reason': str(reason or '')}


CITY_NEWS_WINDOW_S = 24 * 60 * 60
CITY_NEWS_KEEP_S = 7 * 24 * 60 * 60


async def record_city_news(kind: str, headline: str, summary: str = "",
                           icon: str = "🗞", actor_uid=None,
                           dedupe_key: str | None = None) -> bool:
    """Сохраняет газетную заметку. Возвращает False для дубля/ошибки."""
    now = int(time.time())
    kind = str(kind or "city")[:40]
    headline = str(headline or "").strip()[:140]
    summary = str(summary or "").strip()[:360]
    icon = str(icon or "🗞")[:8]
    if not headline:
        return False
    if not dedupe_key:
        # Повтор одного серверного события в пределах минуты не создаёт
        # несколько одинаковых статей (актуально для повторных WS-пакетов).
        dedupe_key = f"{kind}:{actor_uid or ''}:{headline}:{now // 60}"
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            cur = await db.execute(
                "INSERT OR IGNORE INTO city_news "
                "(kind,icon,headline,summary,actor_uid,dedupe_key,created_at) "
                "VALUES (?,?,?,?,?,?,?)",
                (kind, icon, headline, summary,
                 str(actor_uid) if actor_uid is not None else None,
                 str(dedupe_key)[:220], now),
            )
            inserted = cur.rowcount > 0
            await db.execute("DELETE FROM city_news WHERE created_at < ?",
                             (now - CITY_NEWS_KEEP_S,))
            await db.commit()
            return inserted
    except Exception as exc:
        logger.warning("city newspaper write failed: %r", exc)
        return False


async def get_city_news(hours: int = 24, limit: int = 12) -> list:
    hours = max(1, min(168, int(hours or 24)))
    limit = max(1, min(30, int(limit or 12)))
    since = int(time.time()) - hours * 60 * 60
    try:
        async with aiosqlite.connect(DB_PATH) as db:
            db.row_factory = aiosqlite.Row
            async with db.execute(
                "SELECT id,kind,icon,headline,summary,actor_uid,created_at "
                "FROM city_news WHERE created_at>=? "
                "ORDER BY created_at DESC,id DESC LIMIT ?",
                (since, limit),
            ) as cur:
                return [dict(row) for row in await cur.fetchall()]
    except Exception as exc:
        logger.warning("city newspaper read failed: %r", exc)
        return []


