def pick_business_event():
    pool = BUSINESS_EVENTS
    total = sum(e["weight"] for e in pool)
    r = random.uniform(0, total)
    acc = 0
    for e in pool:
        acc += e["weight"]
        if r <= acc:
            return e
    return pool[-1]


