def calc_gang_max(owned_prop: list) -> int:
    """Максимальный размер банды с учётом купленного имущества."""
    bonus = sum(STATUS_ITEMS.get(i, {}).get("gang_bonus", 0) for i in owned_prop)
    return GANG_MAX + bonus
