def _coop_calc_dmg(atk: int, def_: int) -> int:
    import random as _r
    base = max(1, atk - def_ // 2)
    return max(1, round(base * (0.85 + _r.random() * 0.30)))


def _coop_add_log(sess: dict, text: str, typ: str = ''):
    sess['log'].append({'text': text, 'type': typ})
    if len(sess['log']) > 80:
        sess['log'] = sess['log'][-80:]


def _coop_next_turn(sess: dict):
    alive = [p['uid'] for p in sess['players'] if p['hp'] > 0]
    if not alive:
        return
    cur = sess.get('turn_uid')
    if cur in alive:
        idx = (alive.index(cur) + 1) % len(alive)
    else:
        idx = 0
    sess['turn_uid'] = alive[idx]


# ── Лобби: готовность, автостарт, таймаут ────────────────────────────────
# Параметры лобби. Когда все ≥2 игроков нажали «Готов» — старт через
# COOP_READY_AUTOSTART сек. Первое нажатие открывает окно готовности
# COOP_READY_WINDOW сек — если кто-то не нажмёт за это время, сессия
# отменяется автоматически.
COOP_READY_AUTOSTART = 5     # сек до автостарта когда все готовы
COOP_READY_WINDOW    = 60    # сек на нажатие «Готов» всеми после первого «Готов»
COOP_LOBBY_TTL_SEC   = 120   # 2 мин на сессию в waiting (от created_at). Не началась — сгорает.


def _coop_evaluate_lobby(sess: dict, now: float = None) -> None:
    """Проверка состояния лобби — автостарт или таймаут. Вызывается на каждый
    GET/ready, чтобы поллинг с фронта сам двигал состояние без отдельного
    таймера (одной задачи поверх aiohttp нам не нужно)."""
    if sess.get('state') != 'waiting':
        return
    if now is None:
        now = time.time()
    players = sess.get('players') or []
    ready_uids = [p['uid'] for p in players if p.get('ready')]

    # Общий TTL сессии в waiting: 2 минуты от создания. Если хост ушёл,
    # друзей не нашлось и автостарт не сработал — сессия сгорает. Это
    # защищает от «зомби-лобби», висящих в _coop_sessions часами.
    created_at = sess.get('created_at') or now
    if now - created_at > COOP_LOBBY_TTL_SEC:
        sess['state'] = 'cancelled'
        sess['cancel_reason'] = 'lobby_ttl'
        _coop_add_log(sess, "⏱ Сессия не началась за 2 минуты — сгорела.", 'sys')
        return

    # Таймаут готовности: после первого «Готов» даём COOP_READY_WINDOW сек —
    # если не все нажали, отменяем. Если ни один не нажал — таймер не идёт.
    first_ready_at = sess.get('first_ready_at') or 0
    if first_ready_at and len(ready_uids) < len(players):
        if now - first_ready_at > COOP_READY_WINDOW:
            sess['state'] = 'cancelled'
            sess['cancel_reason'] = 'ready_timeout'
            _coop_add_log(sess, "⏱ Кто-то не подтвердил готовность. Сессия отменена.", 'sys')
            return

    # Автостарт: все готовы, минимум 2 игрока → отсчёт COOP_READY_AUTOSTART сек.
    if len(players) >= 2 and ready_uids and len(ready_uids) == len(players):
        if not sess.get('autostart_at'):
            sess['autostart_at'] = now + COOP_READY_AUTOSTART
            _coop_add_log(sess, f"✅ Все готовы. Старт через {COOP_READY_AUTOSTART} сек!", 'sys')
        if now >= sess['autostart_at']:
            sess['state'] = 'battle'
            sess['autostart_at'] = 0
            _coop_init_iso(sess)
            _coop_add_log(sess, "Бой начался!", 'sys')
    else:
        # Если кто-то «отжался» от готовности — гасим автостарт.
        sess['autostart_at'] = 0


def _coop_init_iso(sess: dict) -> None:
    """При переходе в state='battle' раскладываем стартовое состояние для
    iso-боёвки. Сидим единый seed на сессию — все клиенты получают его и
    генерируют одинаковую карту/спавны (Mulberry32 на фронте). Сами позиции
    игроков клиенты досылают через /coop/{sid}/iso как только окажутся в бою."""
    if sess.get('iso_inited'):
        return
    sess['iso_inited'] = True
    import random as _r
    sess['seed'] = _r.randint(1, 999999999)
    sess['iso'] = {
        'players': {
            p['uid']: {
                'x': 0.0, 'y': 0.0, 'ang': 0.0,
                'hp': p['hp'], 'max_hp': p['max_hp'],
                'alive': True,
                'weapon': '',
                'last_update': 0.0,  # 0 = ещё не подключился к iso
            } for p in sess['players']
        }
    }


async def _coop_grant_rewards(sess: dict) -> None:
    """Полный куш каждому живому/не-ливнувшему игроку. Победа в коопе
    раньше шла через бот-handler (web_app_data), HTTP-сесcии награды не
    выдавали вообще. Теперь начисляем тут — без дележа, full reward
    each, ровно как просил продюсер. Ливнувших (`left=True`) пропускаем.

    Лут (boss.drop): один ролл на команду — если выпал, достаётся
    случайному выжившему игроку, у которого этого предмета ещё нет
    (паспорт от Жигана у всех сразу — это перебор и ломает экономику).
    Если ни у кого нет места — лут просто сгорает."""
    if sess.get('rewarded'):
        return
    boss = BOSSES.get(sess.get('boss_id') or '') or {}
    reward_cash = int(boss.get('cash') or 0)
    reward_exp  = int(boss.get('exp')  or 0)
    if not reward_cash and not reward_exp:
        sess['rewarded'] = True
        return
    granted = []
    eligible_uids = []  # uid_int кандидатов на лут
    for pl in sess.get('players') or []:
        if pl.get('left'):
            continue
        try:
            uid_int = int(pl['uid'])
        except Exception:
            continue
        char = await get_character(uid_int)
        if not char:
            continue
        await update_character(
            uid_int,
            cash=(char.get('cash') or 0) + reward_cash,
            exp =(char.get('exp')  or 0) + reward_exp,
            kills=(char.get('kills') or 0) + 1,
        )
        # КРИТИЧНО: без check_level_up exp накапливается, а level не растёт.
        # Игрок видит «опыт обнулился, ранг тот же» — потому что в build_hub_url
        # позже exp_for_level(level) даёт нужное для текущего, новый exp его
        # превышает, но переход в новый ранг сделать некому.
        try:
            _c2 = await get_character(uid_int)
            if _c2:
                await check_level_up(uid_int, _c2)
        except Exception:
            pass
        granted.append(pl['name'])
        eligible_uids.append((uid_int, pl['name']))
    sess['rewarded']    = True
    sess['reward_cash'] = reward_cash
    sess['reward_exp']  = reward_exp
    if granted:
        names = ", ".join(granted)
        _coop_add_log(sess,
            f"💵 Каждому: +${reward_cash} · +{reward_exp} XP ({names})",
            'sys')
    # ── Лут от босса (паспорт от Жигана и т.п.). Один ролл на команду.
    drop = boss.get('drop')
    if drop and eligible_uids:
        drop_item, drop_chance = drop
        if random.random() < drop_chance:
            # Кандидаты: те, у кого этого предмета ещё нет. Если предмет
            # стэкается (medkit и т.п.) — всем подойдёт, у passport
            # ограничение «один на аккаунт» проверяем явно.
            candidates = []
            for uid_int, name in eligible_uids:
                inv = await get_inventory(uid_int)
                if drop_item == 'passport' and drop_item in (inv or {}):
                    continue
                candidates.append((uid_int, name))
            if candidates:
                winner_uid, winner_name = random.choice(candidates)
                await add_item(winner_uid, drop_item)
                item_name = (ITEMS.get(drop_item) or {}).get('name', drop_item)
                sess['reward_drop'] = {
                    'item':    drop_item,
                    'to_uid':  str(winner_uid),
                    'to_name': winner_name,
                }
                _coop_add_log(sess,
                    f"🎁 Дроп: {item_name} → {winner_name}",
                    'sys')
            else:
                _coop_add_log(sess,
                    "💭 Лут выпал, но у всех уже есть...",
                    'sys')
    # Fallback-лут как в соло: 30% шанс трофейного medkit/энергетика
    # каждому. Только если у босса нет «уникального» drop'а.
    elif eligible_uids and random.random() < 0.3:
        loot = random.choice(['medkit_small', 'energy_drink'])
        for uid_int, _ in eligible_uids:
            try:
                await add_item(uid_int, loot)
            except Exception:
                pass
        item_name = (ITEMS.get(loot) or {}).get('name', loot)
        _coop_add_log(sess, f"🎁 Трофей каждому: {item_name}", 'sys')


# ══════════════════════════════════════════════════════════════════
# ISO BATTLE SIMULATOR (Path V — server-authoritative)
# ══════════════════════════════════════════════════════════════════
# Полная симуляция боя на сервере: AI миньонов/босса, пули, физика,
# гранаты — всё крутится тут, клиент только рендерит снапшоты.
# Phase 1 = СКЕЛЕТ: класс + tick-loop + WebSocket transport.
# AI/враги/пули — пока пустые, будут добавлены в фазах 2-5.
# Цель Phase 1 — поднять инфраструктуру и переключить трафик с
# HTTP polling на WS, чтобы дальше уже наращивать симуляцию.
#
# Симулятор крутится 20 Гц (50мс/тик). Каждый клиент держит ОДНО
# постоянное WebSocket-соединение, шлёт через него input в любой
# момент, получает снапшоты каждый тик. Это даёт минимальный
# latency (~50-100мс по сети + 50мс тик-интервал) и не съедает
# батарею на повторных HTTP-запросах — критично для мобильника.

ISO_SIM_TICK_HZ = 20
ISO_SIM_TICK_DT = 1.0 / ISO_SIM_TICK_HZ

# Anti-cheat: rate-limit на t:'hit' от клиента — uid -> [timestamps за 1с].
# Если бот спамит хиты быстрее 40/сек (пистолет ~12-15, автомат ~13), сервер
# их молча дропает. Это не убивает легитимный огонь, но ломает однокадровый
# one-shot-всё-что-движется.
_hit_rate: dict[str, list[float]] = {}

# Phase 8: downed-state параметры.
# DOWN_MAX_SEC — сколько игрок лежит до окончательной смерти, если никто
#                не поднял. 30с — реальный шанс союзнику добежать через
#                всю арену, но и не вечно (давит на темп).
# REVIVE_RADIUS — расстояние, на котором союзник может поднять. 1.8 клеток
#                ≈ «впритык», чтобы под огнём ещё надо было подбежать.
# REVIVE_HP_FRAC — процент max_hp на подъёме. 0.5 — не one-shot но и не full,
#                чтобы поднимать было «дорого тактически».
COOP_DOWN_MAX_SEC = 30.0
COOP_REVIVE_RADIUS = 1.8
COOP_REVIVE_HP_FRAC = 0.5

